# Company configuration: tenants may read their own; only the platform (super admin) path may
# change it. Plant data (limits, plant settings): only users who can see the plant, and no
# platform clause, so the super admin never reads plant-level data.
RLS_POLICIES = """
ALTER TABLE parameters ENABLE ROW LEVEL SECURITY;
CREATE POLICY parameters_read ON parameters FOR SELECT
    USING (app_is_platform() OR company_id = app_company_id());
CREATE POLICY parameters_platform_write ON parameters FOR ALL
    USING (app_is_platform()) WITH CHECK (app_is_platform());

ALTER TABLE treatments ENABLE ROW LEVEL SECURITY;
CREATE POLICY treatments_read ON treatments FOR SELECT
    USING (app_is_platform() OR company_id = app_company_id());
CREATE POLICY treatments_platform_write ON treatments FOR ALL
    USING (app_is_platform()) WITH CHECK (app_is_platform());

ALTER TABLE rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY rules_read ON rules FOR SELECT
    USING (app_is_platform() OR company_id = app_company_id());
CREATE POLICY rules_platform_write ON rules FOR ALL
    USING (app_is_platform()) WITH CHECK (app_is_platform());

ALTER TABLE modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY modules_read ON modules FOR SELECT
    USING (app_is_platform() OR company_id = app_company_id());
CREATE POLICY modules_platform_write ON modules FOR ALL
    USING (app_is_platform()) WITH CHECK (app_is_platform());

ALTER TABLE limits ENABLE ROW LEVEL SECURITY;
CREATE POLICY limits_plant ON limits FOR ALL
    USING (company_id = app_company_id() AND app_can_see_plant(plant_id))
    WITH CHECK (company_id = app_company_id() AND app_can_see_plant(plant_id));

ALTER TABLE plant_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY plant_settings_plant ON plant_settings FOR ALL
    USING (company_id = app_company_id() AND app_can_see_plant(plant_id))
    WITH CHECK (company_id = app_company_id() AND app_can_see_plant(plant_id));
"""


